import * as React from "react";
import { Box } from "@mui/material";
import { useLocation } from "react-router-dom";
import NavigationBar from "./NavigationBar";
import HomePage from "./HomePage";
import VenuesPage from "./VenuesPage";
import HairPage from "./HairPage";
import MakeupPage from "./MakeupPage";
import PhotographersPage from "./PhotographersPage";
import MusicPage from "./MusicPage";
import FloristPage from "./FloristPage";
import DresserPage from "./DresserPage";
import PlannerPage from "./PlannerPage";

export default function NewPage() {
  const location = useLocation();

  // Render content based on selected page, defaulting to HomePage
  const renderContent = () => {
    switch (location.pathname) {
      case "/new/venues":
        return <VenuesPage />;
      case "/new/hair":
        return <HairPage />;
      case "/new/makeup":
        return <MakeupPage />;
      case "/new/photographers":
        return <PhotographersPage />;
      case "/new/music":
        return <MusicPage />;
      case "/new/florist":
        return <FloristPage />;
      case "/new/dresser":
        return <DresserPage />;
      case "/new/planner":
        return <PlannerPage />;
      case "/new": // Load HomePage by default
      default:
        return <HomePage />;
    }
  };

  return (
    <>
      <NavigationBar />
      <Box sx={{ padding: 4 }}>{renderContent()}</Box>
    </>
  );
}



